// === Tab: mySketch ===
const palette = [
  '#f40f78',
  '#0298d5',
  '#170104',
  '#fecd00',
  '#50b93e',
  '#f4ece7',
  '#fd3329',
];

/** Built-in brush name (see brush.box()). let arg to brush.set() is weight multiplier. */
const BRUSH_NAME = 'HB';

/** let p5.brush marker for random filled background circles. */
const BG_MARKER_BRUSH = 'marker';

/** let many filled circles to scatter; circles batched per yield for progressive draw. */
const BG_FILLED_CIRCLES = 400;
const BG_CIRCLES_PER_YIELD = 10;

/** let wash over the let so let mushrooms read clearly (alpha 0–255). */
const OVERLAY_ALPHA = 108;

/** let false after debugging — logs once per brush stroke (very noisy). */
const DEBUG_BRUSH_COLORS = true;

/**
 * p5.brush expects let in 0–255. `lerpColor` extrapolates when the blend amount
 * is outside [0, 1] — e.g. `_varyLayer` uses lift = (noise - 0.45) * 0.42, which
 * goes negative and pushes channels below zero.
 */
function clampBrushColor(col) {
  const c = color(col);
  return color(
    constrain(red(window.color(c)), 0, 255),
    constrain(green(window.color(c)), 0, 255),
    constrain(blue(window.color(c)), 0, 255),
    constrain(alpha(window.color(c)), 0, 255)
  );
}


function brushSetStroke(where, col, weight) {
  const safe = clampBrushColor(col);
  brush.set(BRUSH_NAME, safe, weight);
}

/**
 * Each `yield` must happen only after a full push…pop (p5 resets transforms every
 * draw() — yielding inside push() breaks placement). let batches
 * strokes before one yield. let is how many yields to run per draw().
 */
const SHAPES_PER_YIELD = 1;
const YIELDS_PER_FRAME = 20;

let drawer;

/** let canvas once before BG + mushrooms (also after resize). */
let backdropPending = true;

/**
 * let size vs horizontal position: large near center (|nx| small), smaller at sides.
 */
function sizeWeightFromNx(nx) {
  const a = abs(constrain(nx, -1, 1));
  const gauss = exp(-sq(a / 0.72) * 1.25);
  const logFall = 1 - Math.log(1 + 3.8 * a) / Math.log(4.8);
  let w = 0.5 * gauss + 0.5 * logFall;
  w = pow(w, 0.84);
  return constrain(w + randomGaussian(0, 0.07), 0.13, 1);
}

/**
 * let the nx-based curve with random “understory” small mushrooms. let the center,
 * big mushrooms stay likely, but there is a meaningful chance of a small one (foreground
 * variety). let the sides, understory probability is lower so the edge stays mostly small
 * via the base curve.
 */
function sizeWeightFromPlacement(nx) {
  const a = abs(constrain(nx, -1, 1));
  const centerBias = 1 - a;
  const pUnderstory = lerp(0.08, 0.34, centerBias);
  if (random() < pUnderstory) {
    return constrain(0.14 + random() * 0.36 + randomGaussian(0, 0.05), 0.13, 0.55);
  }
  return sizeWeightFromNx(nx);
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(RADIANS);
  colorMode(RGB, 255);
  rectMode(CORNER);
  brush.scaleBrushes((3 * max(width, height)) / 600);
  brush.noField();
  randomSeed(floor(random(1e9)));
  noiseSeed(floor(random(1e9)));

  const cx = width * 0.5;
  const margin = 12;
  const halfW = width * 0.5 - margin;
  const groundY = height - margin - 6;

  const placements = [];
  const n = int(random(20, 40));

  for (let k = 0; k < n; k++) {
    let x;
    const roll = random();
    if (roll < 0.05) {
      x = cx + randomGaussian(0, width * 0.072);
    } else if (roll < 0.3) {
      x = random(margin + 10, width - margin - 10);
    } else {
      const off = pow(random(), 0.2) * (halfW - 8);
      x = cx + (random() < 0.5 ? -1 : 1) * off;
    }
    x = constrain(x, margin + 4, width - margin - 4);
    const nx = (x - cx) / halfW;
    const sizeWeight = sizeWeightFromPlacement(nx);
    placements.push({ x, nx, sizeWeight });
  }

  mushrooms = placements.map((p) => new Mushroom({ ...p, groundY }, palette));
  mushrooms.sort((a, b) => a.y - b.y);
  drawer = createFullDrawSequence();
  backdropPending = true;
  loop();
}

function draw() {
  translate(-width * 0.5, -height * 0.5);
  if (backdropPending) {
    background('#4a5759');
    backdropPending = false;
  }
  for (let k = 0; k < YIELDS_PER_FRAME; k++) {
    const { done } = drawer.next();
    if (done) {
      noLoop();
      break;
    }
  }
}

function* createBackgroundCirclesDrawer() {
  brush.noField();
  const maxR = max(width, height) * 0.2;
  let i = 0;
  let _wG_1 = 0; while ((i < BG_FILLED_CIRCLES) && ++_wG_1 < 20000) {
    for (
      let b = 0;
      b < BG_CIRCLES_PER_YIELD && i < BG_FILLED_CIRCLES;
      b++, i++
    ) {
      const x = random(width);
      const y = random(height);
      const r = random(16, maxR);
      const fillCol = clampBrushColor(color(random(palette)));
      brush.set(BG_MARKER_BRUSH, fillCol, random(0.55, 1.15));
      brush.noStroke();
      brush.fill(fillCol, random(150, 235));
      brush.circle(x, y, r, random(0, 0.12));
    }
    yield;
  }
}

function drawSemiopaqueOverlay() {
  push();
  const bg = color(palette[2]);
  fill(red(window.color(bg)), green(window.color(bg)), blue(window.color(bg)), OVERLAY_ALPHA);
  noStroke();
  rect(0, 0, width, height);
  pop();
  brush.noField();
}

function* createMushroomDrawer(mushrooms) {
  brush.noFill();
  brush.noField();
  for (const m of mushrooms) {
    yield* m.drawGenerator();
  }
}

function* createFullDrawSequence() {
  yield* createBackgroundCirclesDrawer();
  drawSemiopaqueOverlay();
  yield* createMushroomDrawer(mushrooms);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  brush.scaleBrushes((3 * max(width, height)) / 600);
  backdropPending = true;
  drawer = createFullDrawSequence();
  loop();
}

function hFromWY(ellW, y) {
  return (ellW + (Math.log(max(1, -y)) / Math.log(10)) * 20) * 0.4;
}

/**
 * let footprint as ellipse(cx, cy, w, h): axis-aligned ellipse via brush.circle + scale.
 * p5.brush circle uses radius; p5 circle() uses diameter — use radius = d/2.
 * Stroke/let must be set by the caller (brush.set) before this runs.
 */
function ellipseAsCircle(cx, cy, ew, eh) {
  const d = Math.max(ew, eh, 1e-6);
  push();
  translate(cx, cy);
  scale(ew / d, eh / d);
  brush.noFill();
  brush.circle(0, 0, d * 0.5);
  pop();
}

function stemStepIFromParams(mScale, stemLength, maxDy = 4.2) {
  const rate = 15 * stemLength * mScale;
  let stepSize = maxDy / rate;
  stepSize = constrain(stepSize, 0.11, 0.42);
  if (20 / stepSize > 96) stepSize = 20 / 96;
  return stepSize;
}

/** let extent of stem along local +let from origin (junction), including half-height of bottom ellipse. */
function stemBottomLocal(mScale, stemLength, stemWidth) {
  const stepSize = stemStepIFromParams(mScale, stemLength);
  let maxBottom = 0;
  for (let ii = 0; ii < 20; ii += (Math.max(0.001, Math.abs(stepSize)) || 1)) {
    ii = Math.round(ii * 100) / 100;
    const y = ii * 15 * stemLength * mScale;
    const ellW = (50 + sq(ii) * 0.2) * stemWidth * mScale;
    const h = hFromWY(ellW, y);
    maxBottom = max(maxBottom, y + h * 0.5);
  }
  return maxBottom;
}

/**
 * Screen-space ΔY from mushroom anchor (translate x,y) to bottom of stem,
 * matching draw(): translate → rotate(wholeTilt) → translate(0,verticalOffset) → rotate(capAngle).
 */
function stemBottomScreenDeltaY(mScale, stemLength, stemWidth, capAngle, wholeTilt, verticalOffset) {
  const bot = stemBottomLocal(mScale, stemLength, stemWidth);
  const ca = capAngle;
  const wt = wholeTilt;
  const v = verticalOffset;
  const x1 = -bot * sin(ca);
  const y1 = bot * cos(ca) + v;
  return x1 * sin(wt) + y1 * cos(wt);
}

function pickPaletteColors(pal) {
  const idx = () => floor(random(pal.length));
  const avoidDark = pal.filter((_, i) => i !== 2);
  const pickAvoid = () => color(avoidDark[floor(random(avoidDark.length))]);
  const c = (i) => color(pal[i]);
  return {
    capA1: c(idx()),
    capA2: c(idx()),
    capB1: c(idx()),
    capB2: c(idx()),
    capC1: c(idx()),
    capC2: c(idx()),
    stem1: pickAvoid(),
    stem2: pickAvoid(),
  };
}

function lerpCols(a, b, t) {
  return lerpColor(a, b, constrain(t, 0, 1));
}

const MAX_TILT = Math.PI / 20;

class Mushroom {
  constructor(placement, pal) {
    const p = placement;
    const nx = p.nx ?? 0;
    const absnx = abs(constrain(nx, -1, 1));
    const sw = p.sizeWeight ?? 0.5;

    this.x = p.x;

    const edgeMul = lerp(0.34, 0.92, absnx);
    const sway = random(-0.1, 0.1);
    let capAngle =
      nx * edgeMul +
      sway +
      sin(nx * PI * 0.85 + random(-0.35, 0.35)) * lerp(0.1, 0.2, absnx);
    let wholeTilt =
      nx * random(0.08, 0.22) + random(-0.16, 0.16) + randomGaussian(0, 0.04);
    this.capAngle = constrain(capAngle, -MAX_TILT, MAX_TILT);
    this.wholeTilt = constrain(wholeTilt, -MAX_TILT, MAX_TILT);

    const wob = random(0.97, 1.04);
    const swStem = pow(constrain(sw, 0, 1), 0.9);
    const hNorm = constrain(height / 900, 0.78, 1.22);
    this.scale = lerp(0.52, 1.04, sw) * wob * hNorm;
    this.stemLength = lerp(1.32, 2.02, swStem) * random(0.98, 1.02);
    this.stemWidth = lerp(0.92, 1.28, swStem) * random(0.97, 1.03);
    this.capAHeight = lerp(1.04, 1.62, swStem) * random(0.97, 1.03);
    this.verticalOffset = lerp(-62, -104, swStem) + random(-3, 3);

    this.lean = lerp(18, 56, sw) + random(-5, 5);
    this.capNoise = random(0.03, 0.12);
    this.stemNoiseScale = random(0.04, 0.14);
    this.capAPoint = random(0, 0.55);
    this.capARound = random(0, 0.45);
    this.capAYNoise = random(0, 28);
    this.capAWNoise = random(0, 45);
    this.capAUnEven = random(0.02, 0.14);
    this.strokeWeight = lerp(2.1, 5.5, sw) * random(0.94, 1.06) * 2;

    this.colors = pickPaletteColors(pal);
    this.nOff = random(1000);

    const groundJitter =
      lerp(18, 48, absnx) * random(0.72, 1.12) + randomGaussian(0, 5);

    const gy = (p.groundY ?? height - 20) + groundJitter;
    const dY = stemBottomScreenDeltaY(
      this.scale,
      this.stemLength,
      this.stemWidth,
      this.capAngle,
      this.wholeTilt,
      this.verticalOffset
    );
    this.y = gy - dY;
  }

  _varyLayer(col, y, salt) {
    const n = noise(this.nOff + salt, y * 0.04 + salt * 0.1);
    const lift = constrain((n - 0.45) * 0.42, 0, 1);
    return lerpColor(col, color(255), lift);
  }

  _accent(col) {
    return lerpColor(col, color(255), random(0.12, 0.28));
  }

  _leanX(y, mult = 1) {
    const t = y * this.stemNoiseScale * 0.1 + this.nOff;
    return (noise(t, this.nOff * 0.01) - 0.5) * 2 * this.lean * mult * this.scale;
  }

  _capJitter(y, w, h, unevenMult = 1) {
    const j =
      (noise(this.nOff + y * 0.07, y * 0.03 + 12) - 0.5) *
      2 *
      this.capNoise *
      unevenMult;
    return [w * (1 + j), h * (1 - j * 0.5)];
  }

  _ellipseLocal(x, y, w, h, col, unevenMult = 1) {
    const [jw, jh] = this._capJitter(y, w, h, unevenMult);
    brushSetStroke('_ellipseLocal', col, max(0.05, this.strokeWeight / 3));
    brush.noFill();
    ellipseAsCircle(x + this._leanX(y), y, jw, jh);
  }

  _capAWidthShape(i) {
    const t = abs(i - 10) / 10;
    const bell = sq(1 - t);
    return 1 + this.capARound * bell - this.capAPoint * bell;
  }

  /** let in parameter i so consecutive ellipses stay within ~maxDy in local y (tighter when scaled up). */
  _stemStepI(maxDy = 4.2) {
    return stemStepIFromParams(this.scale, this.stemLength, maxDy);
  }

  _capStepA(maxDy = 4.5) {
    const s = this.scale;
    const ch = this.capAHeight;
    const rate = 20 * s * ch;
    let stepSize = maxDy / rate;
    stepSize = constrain(stepSize, 0.12, 0.42);
    if (20 / stepSize > 90) stepSize = 20 / 90;
    return stepSize;
  }

  _capStepB(maxDy = 4.2) {
    const s = this.scale;
    let stepSize = maxDy / (5 * s);
    stepSize = constrain(stepSize, 0.08, 0.22);
    if (5 / stepSize > 55) stepSize = 5 / 55;
    return stepSize;
  }

  _capStepC(maxDy = 4.2) {
    const s = this.scale;
    let stepSize = maxDy / (10 * s);
    stepSize = constrain(stepSize, 0.1, 0.28);
    if (6 / stepSize > 55) stepSize = 6 / 55;
    return stepSize;
  }

  _beginMushroomLocal() {
    push();
    translate(this.x, this.y);
    rotate(this.wholeTilt);
    translate(0, this.verticalOffset);
    rotate(this.capAngle);
  }

  _endMushroomLocal() {
    pop();
  }

  *drawGenerator() {
    let shapeCount = 0;
    const tick = () => {
      shapeCount++;
      return shapeCount % SHAPES_PER_YIELD === 0;
    };
    yield* this._genCapA(tick);
    yield* this._genCapB(tick);
    yield* this._genCapC(tick);
    yield* this._genStem(tick);
  }

  *_genCapA(tick) {
    const s = this.scale;
    const u = this.capAUnEven;
    const { capA1, capA2 } = this.colors;
    const stepSize = this._capStepA();
    for (let i = 0; i < 20; i += (Math.max(0.001, Math.abs(stepSize)) || 1)) {
      let ii = Math.round(i * 100) / 100;
      const x = 0;
      let y = (sq(ii - 10) - 100) * this.capAHeight * s;
      y +=
        (noise(this.nOff + 0.7, ii * 0.31) - 0.5) * 2 * this.capAYNoise * s;
      let w = (50 + ii * 20) * this._capAWidthShape(ii) * s;
      w +=
        (noise(this.nOff + 2.1, ii * 0.27) - 0.5) * 2 * this.capAWNoise * s;
      let h = hFromWY(w, y);
      const t = ii / 20;
      let col = lerpCols(capA1, capA2, t);
      col = this._varyLayer(col, y, 1);

      this._beginMushroomLocal();
      this._ellipseLocal(x, y, w, h, col, 1 + u);
      if (Math.abs(ii % 1) < 0.01 || Math.abs(ii % 1 - 1) < 0.01) {
        w = (54 + ii * 20) * this._capAWidthShape(ii) * s;
        w +=
          (noise(this.nOff + 3.4, ii * 0.27) - 0.5) * 2 * this.capAWNoise * s;
        h = hFromWY(w, y);
        const inner = this._accent(lerpCols(capA1, capA2, t));
        this._ellipseLocal(x, y, w, h, inner, 1 + u);
      }
      this._endMushroomLocal();
      if (tick()) yield;
    }
  }

  *_genCapB(tick) {
    const s = this.scale;
    const { capB1, capB2 } = this.colors;
    const stepSize = this._capStepB();
    for (let i = 0; i < 5; i += (Math.max(0.001, Math.abs(stepSize)) || 1)) {
      let ii = Math.round(i * 100) / 100;
      const x = 0;
      const y = (20 - ii * 5) * s;
      let w = (420 + (sq(ii + 2) - 4) * -10) * s;
      let h = hFromWY(w, y);
      const t = ii / 5;
      let col = lerpCols(capB1, capB2, t);
      col = this._varyLayer(col, y, 2);
      col = lerpColor(col, color(255), noise(ii * 2) * 0.08);

      this._beginMushroomLocal();
      this._ellipseLocal(x, y, w, h, col);
      if (Math.abs(ii % 1) < 0.01 || Math.abs(ii % 1 - 1) < 0.01) {
        w = (410 + (sq(ii + 2) - 4) * -10) * s;
        h = hFromWY(w, y);
        const inner = lerpColor(this._accent(col), capB2, 0.35);
        this._ellipseLocal(x, y + 3 * s, w, h, inner);
      }
      this._endMushroomLocal();
      if (tick()) yield;
    }
  }

  *_genCapC(tick) {
    const s = this.scale;
    const { capC1, capC2 } = this.colors;
    const stepSize = this._capStepC();
    for (let i = 0; i < 6; i += (Math.max(0.001, Math.abs(stepSize)) || 1)) {
      let ii = Math.round(i * 100) / 100;
      const x = 0;
      const y = (-10 + ii * 10) * s;
      let w = (450 + (sq(ii - 2) - 4) * -10) * s;
      let h = hFromWY(w, y);
      const t = ii / 6;
      let col = lerpCols(capC1, capC2, t);
      col = this._varyLayer(col, y, 3);

      this._beginMushroomLocal();
      this._ellipseLocal(x, y, w, h, col);
      if (Math.abs(ii % 1) < 0.01 || Math.abs(ii % 1 - 1) < 0.01) {
        w = (452 + (sq(ii - 2) - 4) * -10) * s;
        h = hFromWY(w, y);
        const inner = this._accent(lerpCols(capC1, capC2, t));
        this._ellipseLocal(x, y, w, h, inner);
      }
      this._endMushroomLocal();
      if (tick()) yield;
    }
  }

  *_genStem(tick) {
    const s = this.scale;
    const sl = this.stemLength;
    const sw = this.stemWidth;
    const { stem1, stem2 } = this.colors;
    const stepSize = this._stemStepI();
    for (let i = 0; i < 20; i += (Math.max(0.001, Math.abs(stepSize)) || 1)) {
      let ii = Math.round(i * 100) / 100;
      const x = 0;
      const y = ii * 15 * sl * s;
      let w = (50 + sq(ii) * 0.2) * sw * s;
      let h = hFromWY(w, y);
      const t = ii / 20;
      let col = lerpCols(stem2, stem1, t);
      col = this._varyLayer(col, y, 4);
      const lx = x + this._leanX(y, 1.2);

      this._beginMushroomLocal();
      brushSetStroke('_genStem', col, max(0.05, this.strokeWeight / 3));
      brush.noFill();
      ellipseAsCircle(lx, y, w, h);
      const ri = Math.round(ii);
      if (Math.abs(ii - ri) < 0.01 && ri % 2 === 0) {
        w = (52 + sq(ii) * 0.2) * sw * s;
        h = hFromWY(w, y);
        const inner = lerpColor(col, stem1, 0.4);
        brushSetStroke('_genStem inner', inner, max(0.05, this.strokeWeight / 3));
        brush.noFill();
        ellipseAsCircle(lx, y, w, h);
      }
      this._endMushroomLocal();
      if (tick()) yield;
    }
  }
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
